<?php require_once __DIR__.'/../includes/bootstrap.php'; $setup=$_SESSION['setup_2fa']??null;if(!$setup)redirect('/register.php');$q=db()->prepare('SELECT username,email FROM users WHERE id=?');$q->execute([$setup['id']]);$u=$q->fetch();if(!$u){unset($_SESSION['setup_2fa']);redirect('/register.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$code=preg_replace('/\D/','',$_POST['code']??'');if(strlen($code)===6&&totp()->verifyKey($setup['secret'],$code,1)){$q=db()->prepare('UPDATE users SET totp_secret_enc=?,totp_enabled=1 WHERE id=?');$q->execute([encrypt_secret($setup['secret']),$setup['id']]);$q=db()->prepare('SELECT * FROM users WHERE id=?');$q->execute([$setup['id']]);$user=$q->fetch();unset($_SESSION['setup_2fa']);complete_login($user);flash('success','Authenticator verified. Your account is ready.');redirect($user['role']==='ADMIN'?'/admin/dashboard.php':'/dashboard.php');}flash('error','That code was not accepted. Check the authenticator time and try again.');}
$uri=totp()->getQRCodeUrl('Personal Auth',$u['email'],$setup['secret']);render_start('Set up two-factor authentication');?><p class="lede">In your authenticator app, add an account manually using these details. The secret stays on this server encrypted.</p><div class="secret"><?=e($setup['secret'])?></div><p><strong>Type:</strong> Time-based (TOTP), 6 digits, 30 seconds</p><p class="muted">Account: <?=e($u['email'])?></p><p class="muted">You can also use this provisioning URI in a compatible QR tool: <code><?=e($uri)?></code></p><form method="post"><?=csrf_field()?><label>Authenticator code<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required></label><button class="button">Verify and finish</button></form><?php render_end();
